import "package:provider/provider.dart";
import 'package:flutter/material.dart';
import '../app.dart';
class ProfileScreen extends StatelessWidget { const ProfileScreen({super.key}); @override Widget build(BuildContext context){return FutureBuilder<Map<String,dynamic>>(future:context.read<AppState>().repository.profile(),builder:(context,s){if(!s.hasData)return const Scaffold(body:Center(child:CircularProgressIndicator()));final p=s.data!;return Scaffold(appBar:AppBar(title:const Text('Meu perfil')),body:ListView(padding:const EdgeInsets.all(20),children:[ListTile(title:const Text('Nome'),subtitle:Text('${p['name']}')),ListTile(title:const Text('E-mail'),subtitle:Text('${p['email']}')),ListTile(title:const Text('Perfil'),subtitle:Text('${p['role']}')),if(p['member']!=null)ListTile(title:const Text('Status'),subtitle:Text('${p['member']['status']}'))]));});}}
